import {gpuFn} from './gpu-function-scope.js';import * as T from 'three/tsl';
export function sharedRayRecords(raw,u,shared){const functions=new Map();return (id,slot)=>{if(!Number.isInteger(slot)||slot<0||slot>5)throw Error('Ray record slot must be fixed');let fn=functions.get(slot);if(!fn){fn=gpuFn(([id])=>{if(!shared)return raw(u.geometryInfo.w.add(id.mul(6)).add(slot));const at=u.geometryInfo.w.add(id.mul(5));if(slot===3)return T.vec4(raw(at.add(1)).xyz,raw(at.add(2)).w);if(slot===4)return T.vec4(raw(at.add(2)).xyz,raw(at.add(3)).w);if(slot===5)return T.vec4(raw(at.add(3)).xyz,raw(at.add(4)).x);const r=raw(at),result=T.vec4(0).toVar(),valid=r.x.greaterThanEqual(u.geometryRecords.z).and(r.x.add(2).lessThan(u.geometryRecords.y)).and(r.y.greaterThanEqual(0)).and(r.y.add(2).lessThan(u.geometryInfo.w)).and(r.x.equal(r.x.floor())).and(r.y.equal(r.y.floor()));T.If(valid,()=>{const v=raw(r.x.add(slot).sub(u.geometryRecords.x)).xyz,m=[raw(r.y),raw(r.y.add(1)),raw(r.y.add(2))],p=m.map(row=>row.xyz.dot(v).add(slot===0?row.w:0));result.assign(T.vec4(...p,slot===0?r.z:slot===1?r.w:raw(at.add(1)).w));});return result;}).setLayout({name:'hbSceneRecord'+slot,type:'vec4',inputs:[{name:'id',type:'float'}]});functions.set(slot,fn);}return fn(id);};}
